﻿<template>
  <t-form
    ref="form"
    class="item-container login-password"
    :data="formData"
    :rules="FORM_RULES"
    label-width="0"
    @submit="onSubmit"
  >
    <t-form-item name="email">
      <t-input v-model="formData.email" size="large" :placeholder="$t('pages.login.form.emailPlaceholder')" clearable>
        <template #prefix-icon>
          <t-icon name="user" />
        </template>
      </t-input>
    </t-form-item>

    <t-form-item name="password">
      <t-input
        v-model="formData.password"
        size="large"
        :type="showPsw ? 'text' : 'password'"
        clearable
        :placeholder="$t('pages.login.form.passwordPlaceholder')"
      >
        <template #prefix-icon>
          <t-icon name="lock-on" />
        </template>
        <template #suffix-icon>
          <t-icon :name="showPsw ? 'browse' : 'browse-off'" @click="showPsw = !showPsw" />
        </template>
      </t-input>
    </t-form-item>

    <t-form-item class="btn-container">
      <t-button block size="large" type="submit" :loading="loading">{{ $t('pages.login.form.loginBtn') }}</t-button>
    </t-form-item>

    <t-divider v-if="sso.enabled">{{ $t('pages.login.sso.divider') }}</t-divider>

    <t-form-item v-if="sso.enabled" class="btn-container">
      <t-button block size="large" variant="outline" :loading="ssoLoading" @click="onSsoLogin">
        {{ $t('pages.login.sso.btn', { name: sso.displayName || $t('pages.login.sso.defaultName') }) }}
      </t-button>
    </t-form-item>
  </t-form>
</template>
<script setup lang="ts">
import type { FormInstanceFunctions, FormRule, SubmitContext } from 'tdesign-vue-next';
import { MessagePlugin } from 'tdesign-vue-next';
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';

import { getCaptchaSettings } from '@/api/passport';
import { getSsoChallenge, getSsoStatus } from '@/api/sso';
import { t } from '@/locales';
import { useUserStore } from '@/store';
import { getReCaptchaToken } from '@/utils/recaptcha';

const userStore = useUserStore();

const INITIAL_DATA = {
  email: '',
  password: '',
};

const FORM_RULES = computed<Record<string, FormRule[]>>(() => ({
  email: [{ required: true, message: t('pages.login.rules.email'), type: 'error' }],
  password: [{ required: true, message: t('pages.login.rules.password'), type: 'error' }],
}));

const form = ref<FormInstanceFunctions>();
const formData = ref({ ...INITIAL_DATA });
const showPsw = ref(false);
const loading = ref(false);
const sso = ref<{ enabled: boolean; displayName: string }>({ enabled: false, displayName: '' });
const captcha = ref<{ enabled: boolean; siteKey: string }>({ enabled: false, siteKey: '' });
const ssoLoading = ref(false);

const router = useRouter();
const route = useRoute();

// 身份源没配置时后端会返回未启用，这里静默隐藏入口即可
onMounted(async () => {
  try {
    const res: any = await getSsoStatus();
    sso.value = { enabled: Boolean(res.data?.Enabled), displayName: res.data?.DisplayName || '' };
  } catch {
    sso.value = { enabled: false, displayName: '' };
  }

  try {
    const settings: any = await getCaptchaSettings();
    captcha.value = { enabled: Boolean(settings?.Enabled), siteKey: settings?.SiteKey || '' };
  } catch {
    captcha.value = { enabled: false, siteKey: '' };
  }
});

const onSsoLogin = async () => {
  ssoLoading.value = true;
  try {
    const res: any = await getSsoChallenge((route.query.redirect as string) || '');
    // 授权地址必须在浏览器里整页跳转，跨站的 XHR 拿不到重定向后的结果
    window.location.assign(res.data);
  } catch (e: unknown) {
    MessagePlugin.error((e as Error).message || t('pages.login.sso.fail'));
    ssoLoading.value = false;
  }
};

const onSubmit = async (ctx: SubmitContext) => {
  if (ctx.validateResult !== true) {
    return;
  }
  loading.value = true;
  try {
    let captchaToken: string | undefined;
    if (captcha.value.enabled && captcha.value.siteKey) {
      try {
        captchaToken = await getReCaptchaToken(captcha.value.siteKey, 'login');
      } catch {
        MessagePlugin.error(t('pages.login.messages.captchaFail'));
        return;
      }
    }

    await userStore.login({ email: formData.value.email, password: formData.value.password, captchaToken });
    MessagePlugin.success(t('pages.login.messages.loginSuccess'));
    const redirect = route.query.redirect as string;
    router.push(redirect || '/dashboard');
  } catch (e: unknown) {
    MessagePlugin.error((e as Error).message || t('pages.login.messages.loginFail'));
  } finally {
    loading.value = false;
  }
};
</script>
<style lang="less" scoped>
@import '../index.less';
</style>
